from fastapi import FastAPI, HTTPExceptionapp = FastAPI()tasks = [    {"id": 1, "title": "Learn FastAPI", "done": False},    {"id": 2, "title": "Build Task API", "done": False},    {"id": 3, "title": "Push to GitHub", "done": False},]@app.get("/")def read_root():    return {        "name": "Task API",        "version": "1.0",        "endpoints": ["/tasks"]    }@app.get("/health")def health_check():    return {"status": "ok"}@app.get("/tasks")def get_tasks():    return tasks@app.get("/tasks/{task_id}")def get_task(task_id: int):    for task in tasks:        if task["id"] == task_id:            return task    raise HTTPException(status_code=404, detail=f"Task {task_id} not found")@app.post("/tasks", status_code=201)def create_task(new_task: dict):    title = new_task.get("title", "")    if not isinstance(title, str) or not title.strip():        raise HTTPException(status_code=400, detail="title is required and cannot be empty")    next_id = max((task["id"] for task in tasks), default=0) + 1    task = {"id": next_id, "title": title, "done": False}    tasks.append(task)    return task